#include <string.h>
int main(void)  {
    char line[10002];
    int counts[26] =  {
        0
    }
    ;
    // 读取整行而非第一个单词，普通空格不参与字母计数。
    fgets(line, sizeof(line), stdin);
    for (int i = 0; line[i] != '\0'; ++i)  {
        char letter = line[i];
        if (letter >= 'A' && letter <= 'Z')  {
            letter = (char)(letter - 'A' + 'a');
        }
        // 统一小写并确认是字母后才计算 0..25 下标，避免空格越界。
        if (letter >= 'a' && letter <= 'z')  {
            ++counts[letter - 'a'];
        }
    }
    int best = 0;
    for (int i = 1; i < 26; ++i)  {
        // 只在次数严格更多时替换，平局保留字母表中更靠前者。
        if (counts[i] > counts[best])  {
            best = i;
        }
    }
    // 输出选中字母的小写形式与它的总出现次数。
    printf("%c %d\n", 'a' + best, counts[best]);
    return 0;
}

